const e="DAWN",n="The Interactive Mars Rover Experience",t="FISAT Rover Team",a="Federal Institute of Science and Technology (FISAT)",i="Angamaly, Kerala, India",o="Build For Beyond",s="DAWN is an advanced Mars rover prototype engineered by the FISAT Rover Team, a passionate collective of engineering students from FISAT, Angamaly, Kerala. United by a strong enthusiasm for robotics and space technology, the team designs and builds innovative planetary exploration systems while proudly representing India at the International Rover Challenge, a premier global competition.",r="Engineered to operate in Mars-analogue environments, DAWN features an advanced suspension system, a multi-degree-of-freedom robotic arm for precise manipulation, and robust autonomous navigation. Built through strong interdisciplinary collaboration in mechanical, electronics, and software engineering, DAWN is designed to complete complex scientific and maintenance tasks, showcasing innovation and technical excellence.",l="/",c="/fisat/images/logo.png",m="/fisat/images/FISAT_LOGO.png",g=[{label:"Instagram",handle:"@fisatroverteam",url:"https://www.instagram.com/fisatroverteam/"},{label:"LinkedIn",handle:"FISAT Rover",url:"https://www.linkedin.com/company/fisat-rover"},{label:"Institute",handle:"FISAT",url:"https://fisat.ac.in"}],d={name:e,subtitle:n,team:t,institution:a,location:i,tagline:o,mission:s,builtDifferent:r,canonicalUrl:l,logo:c,instituteLogo:m,socials:g};export{r as builtDifferent,l as canonicalUrl,d as default,m as instituteLogo,a as institution,i as location,c as logo,s as mission,e as name,g as socials,n as subtitle,o as tagline,t as team};
